{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "KNI-272, a very close peptidomimetic analogue (transfer 0.969), had absolute oral bioavailability 54.97 ± 19.78% in fasting adult patients, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Atazanavir, a structurally related peptidomimetic HIV protease inhibitor, has absolute oral bioavailability 68% (57–80%) in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Darunavir, another peptidomimetic protease inhibitor, has oral bioavailability 37% in humans, above the 20% threshold despite first-pass metabolism and P-gp efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Sulpiride, a moderately transferable small-molecule drug, has absolute oral bioavailability 27–34% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alvimopan, a lower-transfer analogue with carboxylic acid/zwitterionic character, has absolute oral bioavailability only 6% in humans, arguing against high F in that structural context.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "In children, KNI-272 absolute bioavailability was 12% (range 3.5–25%), a contradictory subpopulation result that tempers but does not overturn the adult high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The highest-transfer evidence (KNI-272, transfer 0.969) shows adult absolute F around 30–55%, clearly above the 20% threshold. Additional related peptidomimetic protease inhibitors (atazanavir, darunavir) also show F 37–68%. Lower-transfer low-F examples (alvimopan, ergotamine, pediatric KNI-272) are less applicable or condition-specific. Overall, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability data for the exact query molecule.",
    "Pediatric KNI-272 data indicate possible subpopulation variability in bioavailability.",
    "Effects of formulation, food, and the query's specific metabolic/transporter profile are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

